  അതെ
{% else %}
  {% set states = {
  'on': 'ഓൺ',
  'off': 'ഓഫ്',
  'open': 'തുറന്നിരിക്കുന്നു',
  'closed': 'അടഞ്ഞിരിക്കുന്നു',
  'opening': 'തുറന്നുകൊണ്ടിരിക്കുന്നു',
  'closing': 'അടഞ്ഞുകൊണ്ടിരിക്കുന്നു',
  'locked': 'പൂട്ടിയിരിക്കുന്നു',
  'unlocked': 'പൂട്ടിയിട്ടില്ല',
  'home': 'വീട്ടിലുണ്ട്',
  'not_home': 'വീട്ടിലില്ല',
  'unknown': 'അറിയില്ല',
  'unavailable': 'ലഭ്യമല്ല'
} %}
