HassGetState.any:
{% if query.matched %}
  {% set names = query.matched | map(attribute="name") | sort | list %}
  അതെ: {{ names[:4] | join(', ') }}{% if names | length > 4 %}, കൂടാതെ {{ names | length - 4 }} {{ 'പേർ' if slots.domain == 'person' else 'എണ്ണം' }}{% endif %}
{% else %}
  ഇല്ല
{% endif %}

HassGetState.all:
{% if query.matched and not query.unmatched %}
  അതെ
{% elif query.unmatched %}
  {% set names = query.unmatched | map(attribute="name") | sort | list %}
  അല്ല. {{ "ഈ സ്ഥലത്തില്ലാത്തവർ" if slots.domain == "person" else "ഈ അവസ്ഥയിലല്ലാത്തവ" }}: {{ names[:4] | join(', ') }}{% if names | length > 4 %}, കൂടാതെ {{ names | length - 4 }} {{ 'പേർ' if slots.domain == 'person' else 'എണ്ണം' }}{% endif %}
{% else %}
  ഒന്നും കണ്ടെത്തിയില്ല
{% endif %}

HassGetState.which:
{% if query.matched %}
  {% set names = query.matched | map(attribute="name") | sort | list %}
  {{ names[:4] | join(', ') }}{% if names | length > 4 %}, കൂടാതെ {{ names | length - 4 }} {{ 'പേർ' if slots.domain == 'person' else 'എണ്ണം' }}{% endif %}
